import React from "react";

export interface ReiconProps extends React.SVGProps<SVGSVGElement> {
  size?: number | string;
  color?: string;
  className?: string;
}

function createReiconComponent(
  displayName: string,
  svgContent: React.ReactNode,
  defaultViewBox = "0 0 24 24"
) {
  const Component = React.forwardRef<SVGSVGElement, ReiconProps>(
    ({ size = 24, color, className = "", style, ...props }, ref) => (
      <svg
        ref={ref}
        width={size}
        height={size}
        viewBox={defaultViewBox}
        fill="none"
        className={className}
        style={{ color: color || undefined, ...style }}
        {...props}
      >
        {svgContent}
      </svg>
    )
  );
  Component.displayName = displayName;
  return Component;
}

